SELECT t1.id, t1.table_code, t1.table_name_en, t1.table_name_chn, t1.module_code, t1.sign, t1.unique_sign,
t1.global_table_flag, t1.owned_enterprise_code, t1.sharding_strategy,
t1.hot_data, t1.dynamic_sorting, t1.create_user_code, t1.table_status, t1.remark, t.base_flag,
t1.update_time, t1.create_time, t1.delete_flag, t1.daily_data_volume, t1.business_flag
FROM dm_base.t_dm_base_module_table t1
WHERE t1.delete_flag = false



            AND t1.owned_enterprise_code is null




                    AND t1.owned_enterprise_code is not null


                    AND t1.owned_enterprise_code = #{moduleTableFilterConditionDTO.ownedEnterpriseCode}






    AND t1.table_status = #{moduleTableFilterConditionDTO.tableStatus}


    AND t1.module_code = #{moduleTableFilterConditionDTO.moduleCode}


    AND (t1.table_name_en LIKE '%' || #{moduleTableFilterConditionDTO.tableName} || '%' OR t1.table_name_chn
    LIKE
    '%'|| #{moduleTableFilterConditionDTO.tableName} || '%')


    AND t1.hot_data = #{moduleTableFilterConditionDTO.hotDataValue}


    AND t1.dynamic_sorting = #{moduleTableFilterConditionDTO.dynamicSorting}


    AND t1.business_flag = #{moduleTableFilterConditionDTO.businessFlag}

SELECT count(*)
FROM dm_base.t_dm_base_module_table t
WHERE t.table_name_en = #{tableNameEn}
  AND t.module_code = #{moduleCode}
  AND t.delete_flag = false

